#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

struct FF {
 private:
  int64 val;
 public:
  FF(int64 v) : val(v) {
    if (v < 0 || v > MOD) {
      cerr << "Invalid value for FF" << endl; exit(1);
    }
  }
  FF() : val(0) {}
  int64 get() const { return val; }
  FF operator+(const FF& o) const {
    FF res(*this); res += o; return res;
  }
  FF operator-(const FF& o) const {
    FF res(*this); res -= o; return res;
  }
  FF operator*(const FF& o) const {
    FF res(*this); res *= o; return res;
  }
  FF operator/(const FF& o) const {
    FF res(*this); res /= o; return res;
  }
  void operator+=(const FF& o) { val = (val + o.val) % MOD; }
  void operator-=(const FF& o) { val = (val + MOD - o.val) % MOD; }
  void operator*=(const FF& o) { val = (val * o.val) % MOD; }
  void operator/=(const FF& o) {
    int64 p = MOD - 2;
    FF base = o;
    FF result(1);
    while (p > 0) {
      if (p & 1) result *= base;
      base *= base;
      p >>= 1;
    }
    *this *= result;
  }
};

template<typename T>
vector<vector<T>> mat_mult(const vector<vector<T>>& a, const vector<vector<T>>& b) {
  int n = a.size(), m = a[0].size(), l = b[0].size();
  vector<vector<T>> res(n, vector<T>(l, 0));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < l; j++) {
      for (int k = 0; k < m; k++) {
        res[i][j] += a[i][k] * b[k][j];
      }
    }
  }
  return res;
}

template<typename T>
vector<T> mat_vec(const vector<vector<T>>& mat, const vector<T>& v) {
  int n = mat.size(), m = v.size();
  vector<T> res(n, 0);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      res[i] += mat[i][j] * v[j];
    }
  }
  return res;
}

template<typename T>
vector<vector<T>> make2D(int d1, int d2, T val) {
  return vector<vector<T>>(d1, vector<T>(d2, val));
}

template<typename T>
vector<vector<vector<T>>> make3D(int d1, int d2, int d3, T val) {
  return vector<vector<vector<T>>>(
      d1, vector<vector<T>>(d2, vector<T>(d3, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int64 n;
  int d;
  cin >> n >> d;

  auto shifts = make3D<FF>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i < d; i++) {
      shifts[k][i][(i + k) % d] = 1;
    }
    shifts[k][d][d] = 1;
  }

  auto units = make3D<FF>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i <= d; i++) {
      units[k][i][i] = 1;
    }
    for (int i = 0; i <= d; i++) {
      units[k][k][i] = 1;
    }
  }

  auto identity = make2D<FF>(d + 1, d + 1, 0);
  for (int i = 0; i <= d; i++) {
    identity[i][i] = 1;
  }

  unordered_map<int64, vector<vector<FF>>> cache;

  function<vector<vector<FF>>(int64)> get_matrix = [&](int64 p) -> vector<vector<FF>> {
    if (cache.count(p)) return cache[p];

    if (p <= d) {
      auto mat = identity;
      for (int k = 0; k < p; k++) {
        mat = mat_mult(units[k], mat);
      }
      cache[p] = mat;
      return mat;
    }

    int64 child_p = d;
    while ((p + child_p - 1) / child_p > d) {
      child_p *= d;
    }
    auto child = get_matrix(child_p);
    auto mat = child;
    int64 rem = p - child_p;
    for (int k = 1; k < d; k++) {
      if (rem >= child_p) {
        mat = mat_mult(shifts[d - k], mat);
        mat = mat_mult(mat, shifts[k]);
        mat = mat_mult(mat, child);
        rem -= child_p;
      } else if (rem > 0) {
        auto rem_mat = get_matrix(rem);
        mat = mat_mult(shifts[d - k], mat);
        mat = mat_mult(mat, rem_mat);
        mat = mat_mult(mat, shifts[k]);
        rem = 0;
      } else {
        break;
      }
    }
    cache[p] = mat;
    return mat;
  };

  auto matrix = get_matrix(n);
  vector<FF> base_vec(d + 1, 0);
  base_vec[d] = 1;
  auto final_vec = mat_vec(matrix, base_vec);
  FF ans = 0;
  for (auto& v : final_vec) ans += v;
  cout << ans.get() << "\n";
}
